import {useCallback,useEffect,useMemo,useState} from "react";
import {ArithmeticWorld} from "./ArithmeticWorld";
import {ReadingWorld} from "./ReadingWorld";
import {AlphabetWorld} from "./AlphabetWorld";
import {CountingWorld,MemoryWorld} from "./PreschoolGames";
import type {FormEvent} from "react";
type PurseType="EXPENSES"|"SAVINGS"|"DONATION";
type Purse={id:string;type:PurseType;balanceAgorot:number};
type Child={id:string;name:string;birthYear:number|null;avatar:string;purses:Purse[]};
type PurseTask={id:string;title:string;frequency:"DAILY"|"WEEKLY";amountAgorot:number;weeklyRequiredCount:number;approvedCountThisWeek:number;approvedToday:boolean;weekStart?:string};
type User={id:string;email:string;name:string;role:"PARENT"|"CHILD";familyId:string};
type AuthMode="login"|"register";
type AllocationPolicy={expensesBps:number;savingsBps:number;donationBps:number;effectiveAt:string};
type SavingsGoal={id:string;title:string;icon:string;targetAgorot:number;active:boolean;achievedAt:string|null;redeemedAt:string|null};
type SavingsGoalState={goal:SavingsGoal|null;balanceAgorot:number;withdrawalsUnlocked:boolean};
type FamilyMonth={month:string;incomeAgorot:number;outflowAgorot:number;netAgorot:number};
type FamilyTransaction={id:string;kind:string;amountAgorot:number;note:string|null;createdAt:string;purseType:PurseType;childName:string};
type FamilyActivity={monthly:FamilyMonth[];recent:FamilyTransaction[]};
type SharedChild=Pick<Child,"id"|"name"|"birthYear"|"avatar"|"purses">&{ageBand:"young"|"middle"|"older";tasks:PurseTask[];savingsGoal:{title:string;icon:string;targetAgorot:number;achievedAt:string|null}|null};
type BeforeInstallPromptEvent=Event&{prompt:()=>Promise<void>;userChoice:Promise<{outcome:"accepted"|"dismissed";platform:string}>};
const meta:Record<PurseType,{label:string;icon:string;description:string;className:string}>={EXPENSES:{label:"הוצאות",icon:"🎒",description:"לדברים שכיף לקנות",className:"expenses"},SAVINGS:{label:"חיסכון",icon:"💎",description:"מגשימים חלום גדול",className:"savings"},DONATION:{label:"תרומה",icon:"🌱",description:"עושים טוב בעולם",className:"donation"}};
const savingsGoalIcons=[{group:"צעצועים ומשחקים",items:["🧸","🪀","🪁","🧩","🎲","🎮","🕹️","🪄"]},{group:"ספורט ופעילות",items:["⚽","🏀","🏈","⚾","🎾","🏓","🚲","🛹","🛼","🛴","🏄","🥋"]},{group:"תחבורה והרפתקאות",items:["🚗","🚙","🏎️","🚕","🚀","✈️","🚁","⛵","🚂","🏕️","🏖️","⛺"]},{group:"טכנולוגיה וגאדג׳טים",items:["📱","💻","⌚","🎧","📷","🎥","🖨️","🔭"]},{group:"חיות וטבע",items:["🐶","🐱","🐰","🐹","🐢","🐠","🦜","🦄","🐉","🌳","🌻","🌈"]},{group:"ספרים, יצירה ואמנות",items:["📚","📖","🎨","🖌️","🎸","🎹","🎤","🧪","🔬"]},{group:"בילויים וחוויות",items:["🎟️","🎡","🎢","🎠","🎪","🍿","🍦","🍕","🧁","🎂"]},{group:"אופנה ואביזרים",items:["👟","👕","🧢","🎒","🕶️","⌚","💍","👑"]},{group:"חלומות ומתנות",items:["🎁","💎","🏆","⭐","🌟","💖","🏰","🗼","🌍","🎯"]}];
const childAvatars=["🧒","👧","👦","🦊","🐼","🐸","🦁","🐯","🐵","🐰","🐻","🐨","🐱","🐶","🦄","🐲","🚀","⭐"];
const money=(n:number)=>new Intl.NumberFormat("he-IL",{style:"currency",currency:"ILS"}).format(n/100);
const transactionKindLabel=(kind:string)=>({INCOME_ALLOCATION:"הפקדת דמי כיס",TASK_REWARD:"תגמול על משימה",EXPENSE:"הוצאה",CASH_REQUEST_PAID:"בקשת כסף",INTEREST_CREDIT:"ריבית",SAVINGS_GOAL_REDEEMED:"משיכה מחיסכון",DONATION_COMPLETED:"תרומה",REVERSAL:"ביטול תנועה"} as Record<string,string>)[kind]??"תנועה בקופה";
async function api<T>(path:string,options:RequestInit={}):Promise<T>{const response=await fetch("/api"+path,{...options,credentials:"include",headers:{...(options.body!==undefined&&options.body!==null?{"Content-Type":"application/json"}:{}),...options.headers}});const data=await response.json().catch(()=>({}));if(!response.ok){const messages:Record<string,string>={account_already_exists:"כבר קיים חשבון עם כתובת המייל הזו",invalid_email_or_password:"כתובת המייל או הסיסמה אינן נכונות",not_authenticated:"צריך להתחבר מחדש",invalid_child:"פרטי הקופה אינם תקינים",child_not_found:"הקופה לא נמצאה או שכבר הוסרה",task_already_approved_today:"המשימה כבר אושרה היום",task_weekly_completed:"המשימה השבועית כבר הושלמה לשבוע הזה",savings_goal_locked:"אי אפשר למשוך כסף לפני שהיעד בקופת החיסכון הושג",insufficient_savings:"אין מספיק כסף בקופת החיסכון",duplicate_withdrawal:"המשיכה הזו כבר נרשמה"};const code=typeof data.error==="string"?data.error:"unknown_error";throw new Error(messages[code]??("שגיאה מהשרת ("+response.status+"): "+code));}return data as T;}
export default function App(){
 const [user,setUser]=useState<User|null>(null),[authMode,setAuthMode]=useState<AuthMode>("register"),[view,setView]=useState<"parent"|"child">("parent");
 const [parentPage,setParentPage]=useState<"overview"|"children"|"finance"|"activity">("overview");
 useEffect(()=>{window.scrollTo({top:0,behavior:"auto"});},[view,parentPage]);
 const shareToken=window.location.pathname.match(/^\/kid\/([A-Za-z0-9_-]{20,})\/?$/)?.[1]??null;
 useEffect(()=>{if(!shareToken&&window.matchMedia("(display-mode: standalone)").matches){const childPath=localStorage.getItem("mypocket-child-pwa-path");if(childPath&&/^\/kid\/[A-Za-z0-9_-]{20,}\/?$/.test(childPath))window.location.replace(childPath);}},[shareToken]);
 const [shareActive,setShareActive]=useState(false),[shareUrl,setShareUrl]=useState("");
 const [familyName,setFamilyName]=useState(""),[parentName,setParentName]=useState(""),[email,setEmail]=useState(""),[password,setPassword]=useState("");
 const [children,setChildren]=useState<Child[]>([]),[selectedId,setSelectedId]=useState(""),[childName,setChildName]=useState(""),[birthYear,setBirthYear]=useState(""),[childAvatar,setChildAvatar]=useState("🧒"),[deleteConfirm,setDeleteConfirm]=useState(false);
 const [busy,setBusy]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState("");
  const [familyActivity,setFamilyActivity]=useState<FamilyActivity>({monthly:[],recent:[]}),[activityLoading,setActivityLoading]=useState(false);
 const [allocation,setAllocation]=useState({expensesBps:5000,savingsBps:3000,donationBps:2000});
 const [savingsGoal,setSavingsGoal]=useState<SavingsGoalState>({goal:null,balanceAgorot:0,withdrawalsUnlocked:false});
 const [goalTitle,setGoalTitle]=useState("");
 const [goalTarget,setGoalTarget]=useState("");
 const [goalIcon,setGoalIcon]=useState("🎯");
 const [editingSavingsGoal,setEditingSavingsGoal]=useState(false);
 const [withdrawAmount,setWithdrawAmount]=useState("");
 const [withdrawNote,setWithdrawNote]=useState("משיכה מקופת חיסכון");
 const [depositAmount,setDepositAmount]=useState(""),[depositNote,setDepositNote]=useState("דמי כיס");
 const [tasks,setTasks]=useState<PurseTask[]>([]),[taskTitle,setTaskTitle]=useState(""),[taskFrequency,setTaskFrequency]=useState<"DAILY"|"WEEKLY">("DAILY"),[taskAmount,setTaskAmount]=useState(""),[taskWeeklyCount,setTaskWeeklyCount]=useState("3");
 const loadChildren=useCallback(async()=>{const result=await api<{children:Child[]}>("/children");setChildren(result.children);setSelectedId(current=>result.children.some(c=>c.id===current)?current:result.children[0]?.id??"");},[]);
  const loadFamilyActivity=useCallback(async()=>{setActivityLoading(true);try{setFamilyActivity(await api<FamilyActivity>("/family/activity"));}finally{setActivityLoading(false);}},[]);
 useEffect(()=>{if(!shareToken)api<{user:User}>("/auth/me").then(r=>setUser(r.user)).catch(()=>{});},[shareToken]);
 useEffect(()=>{if(user&&!shareToken)loadChildren().catch(e=>setError(e.message));},[user,loadChildren,shareToken]);
  useEffect(()=>{if(user&&!shareToken)loadFamilyActivity().catch(e=>setError(e.message));},[user,shareToken,loadFamilyActivity]);
 useEffect(()=>{if(user&&selectedId&&!shareToken){setShareUrl("");api<{policy:AllocationPolicy}>("/children/"+selectedId+"/allocation").then(r=>{if(r.policy)setAllocation({expensesBps:r.policy.expensesBps,savingsBps:r.policy.savingsBps,donationBps:r.policy.donationBps});}).catch(e=>setError(e.message));api<{active:boolean}>("/children/"+selectedId+"/share-link").then(r=>setShareActive(r.active)).catch(()=>setShareActive(false));}},[user,selectedId]);
 const loadSavingsGoal=useCallback(async(childId:string)=>{const result=await api<SavingsGoalState>("/children/"+childId+"/savings-goal");setSavingsGoal(result);setGoalTitle(result.goal?.title??"");setGoalTarget(result.goal?(result.goal.targetAgorot/100).toFixed(2):"");setGoalIcon(result.goal?.icon??"🎯");setEditingSavingsGoal(false);},[]);
 useEffect(()=>{if(user&&selectedId&&!shareToken)loadSavingsGoal(selectedId).catch(e=>setError(e.message));},[user,selectedId,shareToken,loadSavingsGoal]);
 const selected=useMemo(()=>children.find(c=>c.id===selectedId)??children[0],[children,selectedId]);
 const familyOverview=useMemo(()=>children.reduce((totals,child)=>{
  for(const purse of child.purses) totals[purse.type]+=purse.balanceAgorot;
  return totals;
 },{EXPENSES:0,SAVINGS:0,DONATION:0}),[children]);
 const familyTotal=familyOverview.EXPENSES+familyOverview.SAVINGS+familyOverview.DONATION;
  const maxMonthlyFlow=Math.max(1,...familyActivity.monthly.flatMap(item=>[item.incomeAgorot,item.outflowAgorot]));

 useEffect(()=>{if(user&&selectedId&&!shareToken){api<{tasks:PurseTask[]}>("/children/"+selectedId+"/tasks").then(r=>setTasks(r.tasks)).catch(e=>setError(e.message));}},[user,selectedId,shareToken]);
 async function addTask(e:FormEvent){e.preventDefault();if(!selected)return;const amountAgorot=Math.round(Number(taskAmount)*100);if(!Number.isSafeInteger(amountAgorot)||amountAgorot<=0){setError("יש להזין תגמול חיובי למשימה");return;}setBusy(true);setError("");try{await api("/children/"+selected.id+"/tasks",{method:"POST",body:JSON.stringify({title:taskTitle,frequency:taskFrequency,amountAgorot,weeklyRequiredCount:Number(taskWeeklyCount)})});const r=await api<{tasks:PurseTask[]}>("/children/"+selected.id+"/tasks");setTasks(r.tasks);setTaskTitle("");setTaskAmount("");setNotice("המשימה נוספה בהצלחה 🎯");}catch(err){setError(err instanceof Error?err.message:"לא ניתן להוסיף משימה");}finally{setBusy(false);}}
 async function approveTask(task:PurseTask){if(!selected)return;setBusy(true);setError("");try{const result=await api<{credited:boolean;amountAgorot:number;approvedCountThisWeek:number;weeklyRequiredCount:number}>("/children/"+selected.id+"/tasks/"+task.id+"/approve",{method:"POST"});const r=await api<{tasks:PurseTask[]}>("/children/"+selected.id+"/tasks");setTasks(r.tasks);await loadChildren();await loadSavingsGoal(selected.id);await loadFamilyActivity();await loadFamilyActivity();setNotice(result.credited?"המשימה אושרה! "+money(result.amountAgorot)+" חולקו בין שלוש הקופות לפי החלוקה האישית 🎉":"האישור נשמר ("+result.approvedCountThisWeek+"/"+result.weeklyRequiredCount+"). התגמול יועבר לאחר השלמת כל האישורים השבועיים.");}catch(err){setError(err instanceof Error?err.message:"לא ניתן לאשר את המשימה");}finally{setBusy(false);}}
 async function removeTask(task:PurseTask){if(!selected)return;setBusy(true);setError("");try{await api("/children/"+selected.id+"/tasks/"+task.id,{method:"DELETE"});setTasks(old=>old.filter(t=>t.id!==task.id));setNotice("המשימה הוסרה.");}catch(err){setError(err instanceof Error?err.message:"לא ניתן להסיר את המשימה");}finally{setBusy(false);}}
 async function createShareLink(){if(!selected)return;setBusy(true);setError("");setShareUrl("");try{const result=await api<{path:string}>("/children/"+selected.id+"/share-link",{method:"POST"});const url=window.location.origin+result.path;setShareUrl(url);setShareActive(true);try{await navigator.clipboard.writeText(url);setNotice("הקישור האישי של "+selected.name+" הועתק. שלחו אותו לילד/ה.");}catch{setNotice("הקישור נוצר. אפשר להעתיק אותו מהשדה שמופיע כאן.");}}catch(err){setError(err instanceof Error?err.message:"לא ניתן ליצור את הקישור");}finally{setBusy(false);}}
 async function revokeShareLink(){if(!selected)return;setBusy(true);setError("");try{await api("/children/"+selected.id+"/share-link",{method:"DELETE"});setShareActive(false);setNotice("הקישור האישי בוטל ולא יאפשר עוד גישה.");}catch(err){setError(err instanceof Error?err.message:"שגיאה");}finally{setBusy(false);}}
 async function submitAuth(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const body=authMode==="register"?{familyName,parentName,email,password}:{email,password};const r=await api<{user:User}>("/auth/"+(authMode==="register"?"register":"login"),{method:"POST",body:JSON.stringify(body)});setUser(r.user);setNotice(authMode==="register"?"ברוכים הבאים! המשפחה שלכם מוכנה להתחיל 💛":"איזה כיף שחזרתם!");}catch(err){setError(err instanceof Error?err.message:"שגיאה");}finally{setBusy(false);}}
 async function addChild(e:FormEvent){e.preventDefault();setBusy(true);setError("");setNotice("");try{const body={name:childName,avatar:childAvatar,...(birthYear?{birthYear:Number(birthYear)}:{})};const r=await api<{child:Child}>("/children",{method:"POST",body:JSON.stringify(body)});setChildren(old=>[...old,r.child]);setSelectedId(r.child.id);setChildName("");setBirthYear("");setChildAvatar("🧒");setNotice("איזה יופי! שלוש הקופות נוצרו בהצלחה 🎉");}catch(err){setError(err instanceof Error?err.message:"שגיאה");}finally{setBusy(false);}}
 async function deleteSelected(){if(!selected)return;if(!deleteConfirm){setDeleteConfirm(true);return;}setBusy(true);setError("");setNotice("");try{await api("/children/"+selected.id,{method:"DELETE"});const remaining=children.filter(c=>c.id!==selected.id);setChildren(remaining);setSelectedId(remaining[0]?.id??"");setDeleteConfirm(false);setNotice("הקופה הוסרה מהתצוגה הפעילה. היסטוריית התנועות נשמרה.");}catch(err){setError(err instanceof Error?err.message:"שגיאה");}finally{setBusy(false);}}
 async function saveAllocation(e:FormEvent){e.preventDefault();setBusy(true);setError("");setNotice("");try{if(!selected)throw new Error("יש לבחור קופה אישית");await api("/children/"+selected.id+"/allocation",{method:"PUT",body:JSON.stringify(allocation)});setNotice("אחוזי החלוקה של "+selected.name+" נשמרו. הם יחולו על הפקדות חדשות בלבד.");}catch(err){setError(err instanceof Error?err.message:"שגיאה");}finally{setBusy(false);}}
 async function depositIncome(e:FormEvent){e.preventDefault();if(!selected)return;const amount=Math.round(Number(depositAmount)*100);if(!Number.isSafeInteger(amount)||amount<=0){setError("יש להזין סכום חיובי");return;}setBusy(true);setError("");setNotice("");try{const result=await api<{allocation:{expenses:number;savings:number;donation:number};savingsGoalAchieved:boolean}>("/children/"+selected.id+"/income",{method:"POST",body:JSON.stringify({amountAgorot:amount,idempotencyKey:crypto.randomUUID(),note:depositNote||"דמי כיס"})});setDepositAmount("");setNotice("ההפקדה נשמרה וחולקה בהצלחה: הוצאות "+money(result.allocation.expenses)+", חיסכון "+money(result.allocation.savings)+", תרומה "+money(result.allocation.donation)+(result.savingsGoalAchieved?" 🎉 יעד החיסכון הושג!":""));try{await loadChildren();await loadSavingsGoal(selected.id);}catch(refreshError){setError("ההפקדה נשמרה בהצלחה, אך לא ניתן לרענן כרגע את היתרות. רעננו את העמוד בעוד רגע.");}}catch(err){setError(err instanceof Error?err.message:"שגיאה בהפקדה");}finally{setBusy(false);}}
 async function saveSavingsGoal(e:FormEvent){e.preventDefault();if(!selected)return;const targetAgorot=Math.round(Number(goalTarget)*100);if(!goalTitle.trim()||!Number.isSafeInteger(targetAgorot)||targetAgorot<=0){setError("יש להזין שם יעד וסכום חיובי");return;}setBusy(true);setError("");setNotice("");try{const result=await api<SavingsGoalState>("/children/"+selected.id+"/savings-goal",{method:"PUT",body:JSON.stringify({title:goalTitle.trim(),icon:goalIcon,targetAgorot})});setSavingsGoal(result);setEditingSavingsGoal(false);setNotice(result.withdrawalsUnlocked?"היעד כבר הושג! אפשר למשוך מקופת החיסכון.":"יעד החיסכון נשמר. המשיכות נעולות עד להשגת היעד 🔒");}catch(err){setError(err instanceof Error?err.message:"לא ניתן לשמור יעד");}finally{setBusy(false);}}
 async function deleteSavingsGoal(){if(!selected||!savingsGoal.goal)return;if(!window.confirm("למחוק את יעד החיסכון של "+selected.name+"? יתרת הכסף והיסטוריית התנועות יישארו ללא שינוי."))return;setBusy(true);setError("");setNotice("");try{const result=await api<SavingsGoalState>("/children/"+selected.id+"/savings-goal",{method:"DELETE"});setSavingsGoal(result);setGoalTitle("");setGoalTarget("");setGoalIcon("🎯");setEditingSavingsGoal(false);setNotice("יעד החיסכון נמחק. הכסף והיסטוריית התנועות נשארו בקופה.");}catch(err){setError(err instanceof Error?err.message:"לא ניתן למחוק יעד");}finally{setBusy(false);}}
 async function withdrawSavings(e:FormEvent){e.preventDefault();if(!selected)return;const amountAgorot=Math.round(Number(withdrawAmount)*100);if(!Number.isSafeInteger(amountAgorot)||amountAgorot<=0){setError("יש להזין סכום משיכה חיובי");return;}setBusy(true);setError("");setNotice("");try{const result=await api<{withdrawnAgorot:number;balanceAgorot:number}>("/children/"+selected.id+"/savings/withdraw",{method:"POST",body:JSON.stringify({amountAgorot,idempotencyKey:crypto.randomUUID(),note:withdrawNote||"משיכה מקופת חיסכון"})});setWithdrawAmount("");await loadChildren();await loadSavingsGoal(selected.id);setNotice("המשיכה בוצעה: "+money(result.withdrawnAgorot)+". יתרת החיסכון: "+money(result.balanceAgorot));}catch(err){setError(err instanceof Error?err.message:"לא ניתן לבצע משיכה");}finally{setBusy(false);}}
 async function logout(){await api("/auth/logout",{method:"POST"}).catch(()=>{});setUser(null);setChildren([]);setNotice("");setError("");}
 if(shareToken)return <SharedChildPage token={shareToken}/>;
 if(!user)return <main className="shell auth-shell"><header className="topbar"><div className="brand"><img className="brand-logo" src="/pwa-icon.svg?v=4" alt="קופת האוצר" /><div><b>קופת האוצר</b><small>מנהלים כסף בחוכמה</small></div></div><PwaInstallButton/></header><section className="auth-card"><div className="auth-mascot">🦊</div><small className="eyebrow">מתחילים לנהל כסף בכיף</small><h1>{authMode==="register"?"פותחים קופה משפחתית":"טוב שחזרתם!"}</h1><p>חשבון ההורה שלכם הוא המקום הבטוח לניהול הקופות של הילדים.</p><div className="auth-tabs"><button className={authMode==="register"?"active":""} onClick={()=>{setAuthMode("register");setError("");}}>הרשמה</button><button className={authMode==="login"?"active":""} onClick={()=>{setAuthMode("login");setError("");}}>כבר יש לי חשבון</button></div><form onSubmit={submitAuth} className="auth-form">{authMode==="register"&&<><label>שם המשפחה<input required minLength={2} maxLength={80} value={familyName} onChange={e=>setFamilyName(e.target.value)} placeholder="משפחת ישראלי"/></label><label>השם שלך<input required minLength={2} maxLength={80} value={parentName} onChange={e=>setParentName(e.target.value)} placeholder="שם ההורה"/></label></>}<label>כתובת מייל<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" dir="ltr"/></label><label>סיסמה<input required type="password" minLength={authMode==="register"?12:1} maxLength={128} value={password} onChange={e=>setPassword(e.target.value)} placeholder={authMode==="register"?"לפחות 12 תווים":"הסיסמה שלכם"}/></label><button className="primary-button" disabled={busy}>{busy?"רק רגע...":authMode==="register"?"יוצרים חשבון משפחתי ✨":"מתחברים"}</button></form>{error&&<p className="error">{error}</p>}<small className="secure-note">🔒 הסיסמה נשמרת בצורה מוצפנת. אין כאן כסף אמיתי.</small></section></main>;
 return <main className="shell"><header className="topbar"><div className="brand"><img className="brand-logo" src="/pwa-icon.svg?v=4" alt="קופת האוצר" /><div><b>קופת האוצר</b><small>מנהלים כסף בחוכמה</small></div></div><div className="top-actions"><div className="header-quick-actions"><PwaInstallButton/><button className="logout" onClick={logout}>יציאה</button></div>{view==="parent"&&<nav className="parent-page-nav" aria-label="ניווט אזור ההורים"><button className={parentPage==="overview"?"selected":""} onClick={()=>setParentPage("overview")}>תמונת מצב</button><button className={parentPage==="children"?"selected":""} onClick={()=>setParentPage("children")}>הילדים</button><button className={parentPage==="finance"?"selected":""} onClick={()=>setParentPage("finance")}>ניהול כספי</button><button className={parentPage==="activity"?"selected":""} onClick={()=>setParentPage("activity")}>תנועות</button></nav>}<nav className="view-switcher" aria-label="בחירת תצוגה"><button className={view==="parent"?"selected":""} onClick={()=>setView("parent")}>אזור ההורים</button><button className={view==="child"?"selected":""} onClick={()=>setView("child")}>תצוגת ילד</button></nav></div></header>{view==="parent"&&parentPage==="overview"&&<section className="welcome"><div><small className="eyebrow">{view==="parent"?"אזור ההורים":"עולם הילדים"}</small><h1>{view==="parent"?"שלום "+user.name+"! 👋" :"היי "+(selected?.name??"אלוף הכסף")+"! "+(selected?.avatar||"🧒")}</h1><p>{view==="parent"?"כאן מנהלים את הקופות המשפחתיות במקום אחד.":"כל שקל קטן מקרב אותך לחלומות הגדולים שלך."}</p></div><div className="mascot">{view==="parent"?"👨‍👩‍👧‍👦":"🦊"}</div></section>}{notice&&<div className="notice">{notice}</div>}{error&&<div className="error notice-error">{error}</div>}
 {view==="parent"&&parentPage==="overview"&&<><section className="family-overview">
 <div className="overview-heading"><div><small className="eyebrow">התמונה המשפחתית</small><h2>הכסף של המשפחה</h2><p>כל היתרות של הילדים במקום אחד</p></div><span className="overview-icon">📊</span></div>
 <div className="overview-total"><span>סך הכול בכל הקופות</span><strong>{money(familyTotal)}</strong><small>{children.length} {children.length===1?"ילד/ה":"ילדים"} במשפחה</small></div>
 <div className="overview-breakdown">
  <article className="overview-bucket expenses"><span>🛍️ הוצאות</span><strong>{money(familyOverview.EXPENSES)}</strong></article>
  <article className="overview-bucket savings"><span>🚀 חיסכון</span><strong>{money(familyOverview.SAVINGS)}</strong></article>
  <article className="overview-bucket donation"><span>💛 תרומה</span><strong>{money(familyOverview.DONATION)}</strong></article>
 </div>
 <div className="overview-children"><div className="overview-children-heading"><b>יתרה לפי ילד/ה</b><small>לחיצה על כרטיס תציג את פרטי הקופות</small></div>
  {children.length===0?<p className="overview-empty">עדיין לא נוספו ילדים. אפשר להוסיף ילד/ה למטה כדי להתחיל.</p>:<div className="overview-child-list">{children.map(child=><button type="button" key={child.id} className={"overview-child "+(selectedId===child.id?"active":"")} onClick={()=>{setSelectedId(child.id);setParentPage("children");}}><span className="overview-child-avatar">{child.avatar||"🧒"}</span><span className="overview-child-name">{child.name}</span><strong>{money(child.purses.reduce((sum,p)=>sum+p.balanceAgorot,0))}</strong><span className="overview-child-arrow">←</span></button>)}</div>}
 </div>
</section></>}
{view==="parent"&&parentPage==="activity"&&<><section className="activity-panel">
 <div className="activity-panel-heading"><div><small className="eyebrow">מבט לאורך זמן</small><h3>תנועות בחצי השנה האחרונה</h3><p>הפקדות ותגמולים מול משיכות והוצאות שנרשמו ביומן.</p></div><span className="activity-heading-icon">📈</span></div>
 {activityLoading&&familyActivity.monthly.length===0?<p className="overview-empty">טוענים נתונים...</p>:<div className="monthly-chart" role="img" aria-label="תרשים חודשי של כסף שנכנס וכסף שיצא"><div className="monthly-legend"><span><i className="legend-in"/> נכנס</span><span><i className="legend-out"/> יצא</span></div><div className="monthly-bars">{familyActivity.monthly.map(item=><div className="monthly-column" key={item.month}><div className="monthly-bar-pair"><div className="monthly-bar-track"><span className="monthly-bar incoming" style={{height:(item.incomeAgorot/maxMonthlyFlow*100)+"%"}} title={"נכנס: "+money(item.incomeAgorot)}/></div><div className="monthly-bar-track"><span className="monthly-bar outgoing" style={{height:(item.outflowAgorot/maxMonthlyFlow*100)+"%"}} title={"יצא: "+money(item.outflowAgorot)}/></div></div><b>{new Intl.DateTimeFormat("he-IL",{month:"short",timeZone:"UTC"}).format(new Date(item.month+"-01T00:00:00Z"))}</b><small>{item.netAgorot>=0?"+":""}{money(item.netAgorot)}</small></div>)}</div></div>}
 <div className="activity-note">התרשים מבוסס על יומן התנועות. היתרות בקופות הן המדד לסכום הזמין.</div>
</section>
<section className="activity-panel recent-activity">
 <div className="activity-panel-heading"><div><small className="eyebrow">מה קרה לאחרונה</small><h3>תנועות אחרונות</h3><p>עד 30 פעולות אחרונות בכל קופות המשפחה.</p></div><span className="activity-heading-icon">🧾</span></div>
 {familyActivity.recent.length===0?<p className="overview-empty">עדיין אין תנועות ביומן. הפקדה או תגמול ראשון יופיעו כאן.</p>:<div className="transaction-list">{familyActivity.recent.map(item=><article className="transaction-row" key={item.id}><span className={"transaction-icon "+(item.amountAgorot>=0?"positive":"negative")}>{item.amountAgorot>=0?"＋":"−"}</span><div className="transaction-description"><b>{item.note||transactionKindLabel(item.kind)}</b><small>{item.childName} · קופת {meta[item.purseType].label} · {new Date(item.createdAt).toLocaleString("he-IL",{dateStyle:"short",timeStyle:"short"})}</small></div><strong className={item.amountAgorot>=0?"amount-positive":"amount-negative"}>{item.amountAgorot>0?"+":""}{money(item.amountAgorot)}</strong></article>)}</div>}
</section></>}{view==="parent"&&(parentPage==="children"||parentPage==="finance")?<section className="parent-layout">{parentPage==="finance"&&<div className="finance-child-picker"><div className="parent-heading"><div><h2>ניהול כספי</h2><p>ניהול החלוקה, היעדים, ההפקדות והתגמולים.</p></div></div><b>ניהול כספי עבור:</b><div>{children.map(child=><button type="button" key={child.id} className={selectedId===child.id?"active":""} onClick={()=>setSelectedId(child.id)}>{child.avatar||"🧒"} {child.name}</button>)}</div>{children.length===0&&<p>כדי להתחיל, הוסיפו ילד/ה בעמוד „הילדים”.</p>}</div>}{parentPage==="children"&&<><div className="parent-heading"><div><h2>הילדים שלי</h2><p>לכל ילד נוצרות בדיוק שלוש קופות אישיות.</p></div><span className="count-pill">{children.length} ילדים</span></div><form className="add-child" onSubmit={addChild}><div className="add-child-title"><span>🧒</span><div><b>מוסיפים ילד או ילדה</b><small>הקופות ייווצרו אוטומטית ובאופן מאובטח</small></div></div><div className="child-fields"><label>שם הילד/ה<input required maxLength={60} value={childName} onChange={e=>setChildName(e.target.value)} placeholder="למשל: נועה"/></label><label>שנת לידה (לא חובה)<input type="number" min="2000" max={new Date().getFullYear()} value={birthYear} onChange={e=>setBirthYear(e.target.value)} placeholder="2018"/></label><div className="avatar-picker"><span>בחרו אייקון</span><div>{childAvatars.map(icon=><button type="button" key={icon} aria-label={"בחירת אייקון "+icon} aria-pressed={childAvatar===icon} className={childAvatar===icon?"avatar-option active":"avatar-option"} onClick={()=>setChildAvatar(icon)}>{icon}</button>)}</div></div><button className="primary-button" disabled={busy||!childName.trim()}>＋ הוספת ילד/ה</button></div></form>{children.length===0?<div className="empty-state"><span>🪙</span><h3>מתחילים בצעד קטן</h3><p>הוסיפו את הילד הראשון כדי לפתוח עבורו שלוש קופות.</p></div>:<div className="children-grid">{children.map(child=><button key={child.id} className={"child-card "+(selectedId===child.id?"chosen":"")} onClick={()=>setSelectedId(child.id)}><span className="child-avatar">{child.avatar||"🧒"}</span><span className="child-card-name">{child.name}</span><small>{child.birthYear?"יליד/ת "+child.birthYear:"פרופיל ילד/ה"}</small><strong>{money(child.purses.reduce((sum,p)=>sum+p.balanceAgorot,0))}</strong><small>יתרה בשלוש הקופות</small></button>)}</div>}</>}{selected&&<div className="selected-purses">{parentPage==="children"&&<><div className="parent-heading"><div><h2>{selected.avatar||"🧒"} הקופות של {selected.name}</h2><p>היתרות מחושבות מיומן התנועות בשרת.</p></div><button type="button" className="delete-button" onClick={deleteSelected} disabled={busy}>🗑️ מחיקת קופה</button></div>{deleteConfirm&&<div className="delete-confirm"><span>למחוק את הקופה של {selected.name} מהתצוגה הפעילה?</span><small>היסטוריית התנועות תישמר ולא תימחק.</small><div><button type="button" className="delete-button" onClick={deleteSelected} disabled={busy}>כן, למחוק</button><button type="button" className="cancel-button" onClick={()=>setDeleteConfirm(false)}>ביטול</button></div></div>}<section className="share-link-panel"><div><b>📱 הקישור האישי של {selected.name}</b><small>{shareActive?"כבר נוצר קישור פעיל. יצירת קישור חדש תבטל את הקודם.":"צרו קישור פרטי שהילד/ה יוכלו לפתוח בנייד."}</small></div><div><button type="button" className="primary-button" onClick={createShareLink} disabled={busy}>🔗 {shareActive?"יצירת קישור חדש והעתקה":"יצירת קישור והעתקה"}</button>{shareActive&&<button type="button" className="cancel-button" onClick={revokeShareLink} disabled={busy}>ביטול הקישור</button>}</div><small>הקישור מאפשר צפייה בלבד ביתרות של שלוש הקופות ומתעדכן אוטומטית. אפשר לבטל או להחליף אותו בכל עת.</small>{shareUrl&&<input className="share-url-input" aria-label="הקישור האישי של הילד" readOnly dir="ltr" value={shareUrl} onFocus={e=>e.currentTarget.select()} />}</section><PurseCards child={selected}/></>}{parentPage==="finance"&&<><form className="allocation-form" onSubmit={saveAllocation}><div className="allocation-title"><span>⚖️</span><div><b>חלוקת דמי הכיס של {selected.name}</b><small>לכל ילד חלוקה אישית. אפשר לשנות בכל עת; השינוי יחול על הפקדות חדשות בלבד.</small></div></div><div className="allocation-fields"><label>הוצאות (%)<input type="number" min="0" max="100" step="1" value={allocation.expensesBps/100} onChange={e=>setAllocation(v=>({...v,expensesBps:Math.round(Number(e.target.value)*100)}))}/></label><label>חיסכון (%)<input type="number" min="0" max="100" step="1" value={allocation.savingsBps/100} onChange={e=>setAllocation(v=>({...v,savingsBps:Math.round(Number(e.target.value)*100)}))}/></label><label>תרומה (%)<input type="number" min="0" max="100" step="1" value={allocation.donationBps/100} onChange={e=>setAllocation(v=>({...v,donationBps:Math.round(Number(e.target.value)*100)}))}/></label><button className="primary-button" disabled={busy||allocation.expensesBps+allocation.savingsBps+allocation.donationBps!==10000}>שמירת חלוקה</button></div><small className="allocation-total">סה״כ: {(allocation.expensesBps+allocation.savingsBps+allocation.donationBps)/100}% {allocation.expensesBps+allocation.savingsBps+allocation.donationBps===10000?"✓":"— חייבים להגיע ל־100%"}</small></form><section className="savings-goal-panel"><div className="allocation-title"><span>🎯</span><div><b>יעד לקופת החיסכון</b><small>כל עוד היעד לא הושג, אי אפשר למשוך כסף מקופת החיסכון.</small></div></div>{(!savingsGoal.goal||editingSavingsGoal)&&<form className="goal-form" onSubmit={saveSavingsGoal}><label>שם היעד<input required maxLength={80} value={goalTitle} onChange={e=>setGoalTitle(e.target.value)} placeholder="למשל: אופניים חדשים"/></label><label>סכום היעד (₪)<input required type="number" min="0.01" max="21474836.47" step="0.01" value={goalTarget} onChange={e=>setGoalTarget(e.target.value)} placeholder="500"/></label><fieldset className="goal-icon-picker"><legend>בחירת אייקון ליעד</legend><div className="goal-icon-groups">{savingsGoalIcons.map(group=><div className="goal-icon-group" key={group.group}><b>{group.group}</b><div className="goal-icon-options">{group.items.map(icon=><button type="button" key={icon} className={goalIcon===icon?"selected":""} aria-label={"בחירת אייקון "+icon} aria-pressed={goalIcon===icon} onClick={()=>setGoalIcon(icon)}>{icon}</button>)}</div></div>)}</div></fieldset><div className="goal-form-actions"><button className="primary-button" disabled={busy||!goalTitle.trim()||!goalTarget}>{savingsGoal.goal?"שמירת השינויים":"שמירת יעד"}</button>{savingsGoal.goal&&<button type="button" className="cancel-button" disabled={busy} onClick={()=>{setGoalTitle(savingsGoal.goal!.title);setGoalTarget((savingsGoal.goal!.targetAgorot/100).toFixed(2));setGoalIcon(savingsGoal.goal!.icon||"🎯");setEditingSavingsGoal(false);}}>ביטול</button>}</div></form>}{savingsGoal.goal&&<><div className="goal-progress"><div><b className="goal-progress-title"><span aria-hidden="true">{savingsGoal.goal.icon||"🎯"}</span> {savingsGoal.goal.title}</b><span>{money(savingsGoal.balanceAgorot)} מתוך {money(savingsGoal.goal.targetAgorot)}</span></div><div className="goal-track"><span style={{width:Math.min(100,Math.max(0,savingsGoal.balanceAgorot/savingsGoal.goal.targetAgorot*100))+"%"}}/></div><small>{savingsGoal.withdrawalsUnlocked?"🔓 היעד הושג — המשיכות פתוחות":"🔒 המשיכות נעולות עד להשגת היעד"}</small></div>{!editingSavingsGoal&&<div className="goal-management-actions"><button type="button" className="primary-button" disabled={busy} onClick={()=>setEditingSavingsGoal(true)}>✏️ עריכת יעד</button><button type="button" className="cancel-button" disabled={busy} onClick={deleteSavingsGoal}>🗑️ מחיקת יעד</button></div>}</>}{savingsGoal.withdrawalsUnlocked&&<form className="withdraw-form" onSubmit={withdrawSavings}><b>משיכה מקופת החיסכון</b><label>סכום למשיכה (₪)<input required type="number" min="0.01" max="21474836.47" step="0.01" value={withdrawAmount} onChange={e=>setWithdrawAmount(e.target.value)} placeholder="לדוגמה: 50"/></label><label>הערה (לא חובה)<input maxLength={160} value={withdrawNote} onChange={e=>setWithdrawNote(e.target.value)}/></label><button className="primary-button" disabled={busy||!withdrawAmount}>ביצוע משיכה</button></form>}</section><form className="deposit-form" onSubmit={depositIncome}><div className="allocation-title"><span>🪙</span><div><b>הפקדת דמי כיס</b><small>ההפקדה תחולק אוטומטית לפי אחוזי המשפחה</small></div></div><div className="deposit-fields"><label>סכום בשקלים<input required type="number" min="0.01" max="21474836.47" step="0.01" value={depositAmount} onChange={e=>setDepositAmount(e.target.value)} placeholder="לדוגמה: 20"/></label><label>הערה (לא חובה)<input maxLength={160} value={depositNote} onChange={e=>setDepositNote(e.target.value)} placeholder="דמי כיס שבועיים"/></label><button className="primary-button" disabled={busy||!depositAmount}>הפקדה וחלוקה</button></div></form><section className="task-manager"><div className="allocation-title"><span>⭐</span><div><b>משימות ותגמולים</b><small>מגדירים משימה ותגמול שמתחלק אוטומטית בין שלוש הקופות לפי החלוקה האישית של הילד.</small></div></div><form className="task-create-form" onSubmit={addTask}><label>שם המשימה<input required maxLength={80} value={taskTitle} onChange={e=>setTaskTitle(e.target.value)} placeholder="למשל: לסדר את החדר"/></label><label>תגמול (₪)<input required type="number" min="0.01" max="21474836.47" step="0.01" value={taskAmount} onChange={e=>setTaskAmount(e.target.value)} placeholder="5"/></label><label>תדירות<select value={taskFrequency} onChange={e=>setTaskFrequency(e.target.value as "DAILY"|"WEEKLY")}><option value="DAILY">יומית — תגמול בכל יום</option><option value="WEEKLY">שבועית — צבירת אישורים</option></select></label>{taskFrequency==="WEEKLY"&&<label>כמה אישורים בשבוע?<select value={taskWeeklyCount} onChange={e=>setTaskWeeklyCount(e.target.value)}>{[2,3,4,5,6,7].map(n=><option key={n} value={n}>{n} פעמים</option>)}</select></label>}<button className="primary-button" disabled={busy||!taskTitle.trim()||!taskAmount}>＋ הוספת משימה</button></form><div className="task-list">{tasks.length===0?<p className="task-empty">עדיין לא הוגדרו משימות. אפשר להתחיל במשימה יומית או שבועית.</p>:tasks.map(task=><article className="task-item" key={task.id}><div className="task-item-main"><b>{task.title}</b><small>{task.frequency==="DAILY"?"יומית":"שבועית"} · תגמול כולל {money(task.amountAgorot)} לכל הקופות</small><small>{task.frequency==="DAILY"?(task.approvedToday?"אושרה היום":"ממתינה לאישור היום"):"התקדמות השבוע: "+task.approvedCountThisWeek+"/"+task.weeklyRequiredCount}</small></div><div className="task-actions"><button type="button" className="primary-button" disabled={busy||task.approvedToday||(task.frequency==="WEEKLY"&&task.approvedCountThisWeek>=task.weeklyRequiredCount)} onClick={()=>approveTask(task)}>{task.approvedToday?"אושר היום":task.frequency==="WEEKLY"&&task.approvedCountThisWeek>=task.weeklyRequiredCount?"הושלם השבוע":"אישור ביצוע"}</button><button type="button" className="cancel-button" disabled={busy} onClick={()=>removeTask(task)}>הסרה</button></div></article>)}</div></section></>}</div>}</section>:view==="child"&&selected?<ChildAdventure child={selected} tasks={tasks} savingsGoal={savingsGoal.goal?{title:savingsGoal.goal.title,icon:savingsGoal.goal.icon,targetAgorot:savingsGoal.goal.targetAgorot,achievedAt:savingsGoal.goal.achievedAt}:null}/>:view==="child"?<div className="empty-state"><span>🦊</span><h3>עוד אין קופות להצגה</h3><p>בקשו מההורה להוסיף אתכם באזור ההורים.</p><button className="primary-button" onClick={()=>setView("parent")}>לאזור ההורים</button></div>:null}<footer>💚 קופת האוצר · חוסכים, לומדים, מגשימים</footer></main>;
}
function TaskProgress({tasks}:{tasks:PurseTask[]}){return <section className="task-progress"><div className="task-list">{tasks.length===0?<p className="task-empty">אין משימות חדשות כרגע. אפשר ליהנות מהקופות ולהמשיך להתקדם! 🦊</p>:tasks.map(task=><article className="task-item" key={task.id}><div className="task-item-main"><b>{task.title}</b><small>תגמול כולל {money(task.amountAgorot)} לכל הקופות</small><small>{task.frequency==="DAILY"?(task.approvedToday?"כל הכבוד! אושר היום":"אפשר לקבל אישור פעם אחת ביום"):"התקדמות השבוע: "+task.approvedCountThisWeek+"/"+task.weeklyRequiredCount+" אישורים"}</small></div><span className="task-status">{task.frequency==="DAILY"?(task.approvedToday?"✓":"יומית"):(task.approvedCountThisWeek>=task.weeklyRequiredCount?"✓ הושלם":"שבועית")}</span></article>)}</div></section>;}
function PurseCards({child,savingsGoal=null}:{child:Pick<Child,"purses">;savingsGoal?:{title:string;icon:string;targetAgorot:number;achievedAt:string|null}|null}){const savings=child.purses.find(p=>p.type==="SAVINGS")?.balanceAgorot??0;const progress=savingsGoal?Math.min(100,Math.max(0,savings/savingsGoal.targetAgorot*100)):0;return <section className="purses" aria-label="שלוש הקופות האישיות">{(["EXPENSES","SAVINGS","DONATION"] as PurseType[]).map(type=>{const item=meta[type],purse=child.purses.find(p=>p.type===type);return <article className={"purse "+item.className} key={type}><div className="purse-head"><span aria-hidden="true">{item.icon}</span></div><h3>קופת {item.label}</h3><strong>{money(purse?.balanceAgorot??0)}</strong><p>{item.description}</p>{type==="SAVINGS"&&<div className="purse-savings-destination">{savingsGoal?<><div className="purse-savings-goal"><span aria-hidden="true">{savingsGoal.icon||"🎯"}</span><div><small>חוסכים בשביל</small><b>{savingsGoal.title}</b></div></div><div className="purse-savings-track" role="progressbar" aria-label={"התקדמות אל "+savingsGoal.title} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(progress)}><span style={{width:progress+"%"}}/></div><div className="purse-savings-caption"><span>{savingsGoal.achievedAt?"🎉 החלום הושג!":"כבר צברת "+money(savings)}</span><b>{Math.round(progress)}%</b></div><small className="purse-savings-remaining">{savingsGoal.achievedAt?"כל הכבוד! הצלחת להגשים את החלום 🏆":"עוד "+money(Math.max(0,savingsGoal.targetAgorot-savings))+" עד שמגיעים ליעד"}</small></>:<div className="purse-savings-no-goal"><span>🗺️</span><span>עוד אין חלום לחיסכון. בקש מההורה לבחור לך יעד להרפתקה!</span></div>}</div>}</article>;})}</section>;}

function PwaInstallButton(){
 const [installPrompt,setInstallPrompt]=useState<BeforeInstallPromptEvent|null>(null);
 const [help,setHelp]=useState(false);
 const [installed,setInstalled]=useState(false);
 useEffect(()=>{
  const onPrompt=(event:Event)=>{event.preventDefault();setInstallPrompt(event as BeforeInstallPromptEvent);};
  const onInstalled=()=>{setInstalled(true);setInstallPrompt(null);setHelp(false);};
  window.addEventListener("beforeinstallprompt",onPrompt);
  window.addEventListener("appinstalled",onInstalled);
  if(window.matchMedia("(display-mode: standalone)").matches||(navigator as Navigator&{standalone?:boolean}).standalone)setInstalled(true);
  return ()=>{window.removeEventListener("beforeinstallprompt",onPrompt);window.removeEventListener("appinstalled",onInstalled);};
 },[]);
 async function install(){
  if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice.outcome==="accepted")setInstalled(true);setInstallPrompt(null);return;}
  setHelp(value=>!value);
 }
 if(installed)return <span className="pwa-installed" aria-label="האפליקציה מותקנת">✓ מותקן</span>;
 const canInstall=Boolean(installPrompt);
 return <div className="pwa-install-wrap"><button type="button" className="pwa-install-button" onClick={install}>⬇ {canInstall?"התקנת האפליקציה":"התקנה / עזרה"}</button>{help&&<div className="pwa-help" role="status"><b>איך מתקינים?</b><span>ב־iPhone: פותחים ב־Safari, לוחצים על שיתוף ואז „הוספה למסך הבית”.</span><span>ב־Android או במחשב: פותחים את תפריט הדפדפן ובוחרים „התקנת האפליקציה” או „הוספה למסך הבית”.</span></div>}</div>;
}

function ChildAdventure({child,tasks,savingsGoal,onRefresh,updatedAt}:{child:{id:string;name:string;birthYear?:number|null;avatar:string;purses:Purse[];ageBand?:"young"|"middle"|"older"};tasks:PurseTask[];savingsGoal:{title:string;icon:string;targetAgorot:number;achievedAt:string|null}|null;onRefresh?:()=>void;updatedAt?:Date}){
 const [page,setPage]=useState<"journey"|"games"|"purses"|"tasks"|"achievements">("journey");
 const [gameMode,setGameMode]=useState<"math"|"reading"|"counting"|"memory">("math");
 const total=child.purses.reduce((sum,p)=>sum+p.balanceAgorot,0);
 const savings=child.purses.find(p=>p.type==="SAVINGS")?.balanceAgorot??0;
 const age=child.birthYear?new Date().getFullYear()-child.birthYear:null;
 const ageBand=child.ageBand??(age!==null&&age<=7?"young":age!==null&&age>=11?"older":"middle");
 const preschool=child.birthYear!==undefined&&child.birthYear!==null&&child.birthYear<=2021;
 const copy=ageBand==="young"?{greeting:"איזה כיף שבאת להרפתקה!",journey:"הדרך אל האוצר",purses:"האוצרות שלי",tasks:"המשימות שלי",tip:"כל מטבע קטן עוזר לחלום לגדול!",level:"מגלי אוצרות"}:ageBand==="older"?{greeting:"ההתקדמות שלך נראית מצוין.",journey:"תוכנית החיסכון שלי",purses:"היתרות שלי",tasks:"המשימות והתגמולים שלי",tip:"תכנון קטן היום נותן לך יותר אפשרויות מחר.",level:"מתכנני אוצר"}:{greeting:"כל צעד קטן מקרב אותך לחלום!",journey:"המסע אל החלום",purses:"שלוש הקופות שלי",tasks:"המשימות שלי",tip:"כשחוסכים קצת בכל פעם, החלום מתקרב!",level:"הרפתקני אוצר"} as const;
 const completedTasks=tasks.filter(task=>task.frequency==="DAILY"?task.approvedToday:task.approvedCountThisWeek>=task.weeklyRequiredCount).length;
 const badges=[{icon:"🪙",title:"צעד ראשון",earned:total>0},{icon:"🚀",title:"מתקדמים בחיסכון",earned:savings>0},{icon:"⭐",title:"משימה הושלמה",earned:tasks.some(task=>task.approvedToday||task.approvedCountThisWeek>0)},{icon:"💛",title:"לב נדיב",earned:(child.purses.find(p=>p.type==="DONATION")?.balanceAgorot??0)>0},{icon:"🏆",title:"החלום הושג",earned:Boolean(savingsGoal?.achievedAt)}];
 const progress=savingsGoal?Math.min(100,Math.max(0,savings/savingsGoal.targetAgorot*100)):0;
 const isAmy=["איימי","Amy"].includes(child.name.trim());
 return <div className={"child-world child-age-"+ageBand}>
  <section className="adventure-hero">
   <div className="adventure-hero-copy"><span className="adventure-kicker">🦊 עולם האוצר שלך</span><h1>היי {child.name}!</h1><p>{copy.greeting}</p><span className="adventure-level">{copy.level}</span></div>
   <div className="fox-companion" aria-label="השועל החכם שמלווה אותך במסע"><svg className="fox-guide-art" viewBox="0 0 120 142" role="img" aria-label="שועל הרפתקן כתום עם צעיף ירוק"><ellipse cx="61" cy="132" rx="34" ry="6" fill="#203b4b" opacity=".13"/><path d="M83 91c29-4 35 17 21 29-8 7-20 1-18-8 2-6 9-7 13-3-1-10-10-11-20-7" fill="#c96c36" stroke="#8e472e" strokeWidth="3" strokeLinecap="round"/><path d="M38 72 26 111q-2 10 8 10h44q10 0 8-10L75 72" fill="#df813d" stroke="#8e472e" strokeWidth="3" strokeLinejoin="round"/><path d="m43 91 17 10 17-10-4 23H47z" fill="#f8e5bd"/><path d="m39 75 9 11 12-7 12 7 9-11-5 27H44z" fill="#2f8b72"/><path d="M25 41 19 8q-1-7 6-3l24 19M95 41l6-33q1-7-6-3L71 29" fill="#df813d" stroke="#8e472e" strokeWidth="3" strokeLinejoin="round"/><path d="m29 31-3-16 14 13M91 31l3-16-14 13" fill="#f6c5a0"/><path d="M22 49q0-34 38-34t38 34q0 35-38 42Q22 84 22 49" fill="#e88945" stroke="#8e472e" strokeWidth="3"/><path d="M31 58q0-19 16-19 12 0 13 15-1 18-15 20-14-2-14-16M89 58q0-19-16-19-12 0-13 15 1 18 15 20 14-2 14-16" fill="#fff4df"/><ellipse cx="45" cy="51" rx="3.5" ry="5" fill="#293746"/><ellipse cx="75" cy="51" rx="3.5" ry="5" fill="#293746"/><path d="M53 66q7-7 14 0-3 8-7 8t-7-8" fill="#6e3d31"/><path d="M58 74q2 5 5 0" fill="none" stroke="#6e3d31" strokeWidth="2" strokeLinecap="round"/><path d="m48 116-4 12m30-12 4 12" stroke="#8e472e" strokeWidth="5" strokeLinecap="round"/></svg><span>קדימה להרפתקה!</span></div>
   <div className="adventure-spark adventure-spark-one">✦</div><div className="adventure-spark adventure-spark-two">✧</div>
  </section>
  <section className="adventure-total"><div><span>האוצר שצברת עד היום</span><strong>{money(total)}</strong><small>בכל שלוש הקופות שלך</small></div><div className="adventure-coin">🪙</div></section>
  {page==="journey"&&<section className="adventure-section" id="child-journey">
   <div className="adventure-section-heading"><div><span className="adventure-eyebrow">החלום הבא שלך</span><h2>🚀 {copy.journey}</h2></div>{onRefresh&&<button type="button" className="adventure-refresh" onClick={onRefresh}>↻ רענון</button>}</div>
   {savingsGoal?<div className="journey-card"><div className="journey-card-top"><div className="journey-goal-title"><span className="journey-goal-icon" aria-hidden="true">{savingsGoal.icon||"🎯"}</span><div><b>{savingsGoal.title}</b><small>{savingsGoal.achievedAt?"הגעת ליעד! איזה הישג מדהים 🎉":"כל הפקדה מקרבת אותך עוד קצת"}</small></div></div><span className="journey-percent">{Math.round(progress)}%</span></div><div className="journey-visual"><div className="journey-planet">🪐</div><div className="journey-track"><span style={{width:progress+"%"}}/></div><div className="journey-treasure">🎁</div></div><div className="journey-amounts"><b>{money(savings)}</b><span>מתוך {money(savingsGoal.targetAgorot)}</span></div>{!savingsGoal.achievedAt&&<p className="journey-encouragement">{progress>=75?"כמעט שם! עוד קצת והאוצר שלך 🎉":progress>=35?"איזה יופי, כבר התקדמת יפה!":"המסע מתחיל בצעד קטן. אתה בדרך!"}</p>}</div>:<div className="journey-empty"><span>🗺️</span><div><b>עוד לא בחרנו יעד למסע</b><p>בקש מההורה להגדיר חלום לחיסכון, ונצא לדרך!</p></div></div>}
    {isAmy&&<div className="genie-wish-callout"><div className="genie-wish-copy"><span className="genie-wish-spark">✦ משאלה קטנה, חלום גדול ✦</span><h3>בקשי משאלה מהג'יני</h3><p>עצמי עיניים, חשבי על משהו שמשמח אותך, ותני לחלום שלך כנפיים ✨</p></div><div className="genie-float" role="img" aria-label="איור של ג'יני קסום מרחף"><svg viewBox="0 0 150 160" className="genie-art" aria-hidden="true"><defs><linearGradient id="genieBody" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#a78bfa"/><stop offset="1" stopColor="#6554c0"/></linearGradient><linearGradient id="genieTail" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#70e1d1"/><stop offset="1" stopColor="#239b9b"/></linearGradient></defs><path d="M72 119c-21 13-31 23-18 29 15 7 42-5 36-15-4-6-15-7-18-14" fill="url(#genieTail)" opacity=".95"/><path d="M53 93c-17 9-24 18-17 24 7 6 23 1 34-8l8-12" fill="url(#genieTail)"/><path d="M59 76c-8 9-13 20-10 30 4 14 26 16 42 7 16-9 20-22 9-34l-9-12" fill="url(#genieBody)" stroke="#51439b" strokeWidth="3"/><path d="M56 86c-10-8-20-8-25-1 7 12 17 17 28 15M92 85c12-10 23-8 28 0-7 12-18 17-29 14" fill="#8b7ae2" stroke="#51439b" strokeWidth="3" strokeLinecap="round"/><path d="M52 74c-3-21 5-37 24-38 20-1 29 17 22 38-7 18-38 18-46 0" fill="#f0c49a" stroke="#9d694f" strokeWidth="3"/><path d="M49 51c2-22 20-31 39-23 8 3 13 10 13 19-10-5-17-10-22-18-4 13-16 20-30 22" fill="#3f2d78"/><path d="M65 59q4-4 8 0m10 0q4-4 8 0" fill="none" stroke="#513b43" strokeWidth="3" strokeLinecap="round"/><path d="M72 70q7 6 14 0" fill="none" stroke="#a85e5c" strokeWidth="2.5" strokeLinecap="round"/><path d="M60 39q16-10 32 0" fill="none" stroke="#f4d36c" strokeWidth="5" strokeLinecap="round"/><path d="M73 94q5 9 10 0" fill="none" stroke="#f4d36c" strokeWidth="5" strokeLinecap="round"/><circle cx="111" cy="37" r="5" fill="#f5cf63"/><path d="m111 24 2 8 7 3-7 2-2 8-2-8-7-2 7-3z" fill="#ffe49a"/><path d="m27 45 2 6 6 2-6 2-2 6-2-6-6-2 6-2z" fill="#ffe49a"/><path d="M45 119q-13 5-14 15" fill="none" stroke="#f4d36c" strokeWidth="3" strokeLinecap="round"/></svg></div></div>}
  </section>}
  {page==="purses"&&<section className="adventure-section" id="child-purses"><div className="adventure-section-heading"><div><span className="adventure-eyebrow">הכסף שלך מחולק בחוכמה</span><h2>💰 {copy.purses}</h2></div></div><PurseCards child={child} savingsGoal={savingsGoal}/></section>}
  {page==="tasks"&&<section className="adventure-section" id="child-tasks"><div className="adventure-section-heading"><div><span className="adventure-eyebrow">כל משימה היא הזדמנות</span><h2>🎯 {copy.tasks}</h2></div>{tasks.length>0&&<span className="task-count">{completedTasks}/{tasks.length} הושלמו</span>}</div><TaskProgress tasks={tasks}/></section>}
  {page==="achievements"&&<section className="adventure-section" id="child-achievements"><div className="adventure-section-heading"><div><span className="adventure-eyebrow">דברים טובים שכבר עשית</span><h2>🏆 אוסף ההישגים שלי</h2></div></div><div className="achievement-grid">{badges.map(badge=><div className={"achievement-badge "+(badge.earned?"earned":"locked")} key={badge.title}><span>{badge.icon}</span><b>{badge.title}</b><small>{badge.earned?"הישג פתוח!":"עוד בדרך"}</small></div>)}</div></section>}
  {page==="games"&&<section className="adventure-section" id="child-games">{preschool?<><div className="adventure-section-heading"><div><span className="adventure-eyebrow">משחקים, לומדים ומגלים</span><h2>🌈 עולם המשחקים לקטנטנים</h2></div><span className="task-count">לגיל הרך</span></div><div className="learning-mode-tabs preschool-game-tabs" role="tablist" aria-label="בחירת משחק"><button type="button" role="tab" aria-selected={gameMode!=="counting"&&gameMode!=="memory"} className={gameMode!=="counting"&&gameMode!=="memory"?"active":""} onClick={()=>setGameMode("letters")}>🔤 אותיות</button><button type="button" role="tab" aria-selected={gameMode==="counting"} className={gameMode==="counting"?"active":""} onClick={()=>setGameMode("counting")}>🔟 סופרים</button><button type="button" role="tab" aria-selected={gameMode==="memory"} className={gameMode==="memory"?"active":""} onClick={()=>setGameMode("memory")}>🧠 זיכרון</button></div>{gameMode==="counting"?<CountingWorld/>:gameMode==="memory"?<MemoryWorld/>:<AlphabetWorld childName={child.name}/>}</>:<><div className="adventure-section-heading"><div><span className="adventure-eyebrow">משחקים, לומדים ומתקדמים</span><h2>🎮 עולם הלמידה</h2></div><span className="task-count">משחקי למידה</span></div><div className="learning-mode-tabs" role="tablist" aria-label="בחירת סוג משחק"><button type="button" role="tab" aria-selected={gameMode==="math"} className={gameMode==="math"?"active":""} onClick={()=>setGameMode("math")}>➕ משחקי חשבון</button><button type="button" role="tab" aria-selected={gameMode==="reading"} className={gameMode==="reading"?"active":""} onClick={()=>setGameMode("reading")}>📚 משחקי קריאה</button></div>{gameMode==="math"?<ArithmeticWorld childId={child.id} ageBand={ageBand}/>:<ReadingWorld childId={child.id} ageBand={ageBand}/>}</>}</section>}
  {page==="journey"&&<section className="fox-tip"><span className="fox-tip-mascot">🦊</span><div><b>טיפ מהשועל החכם</b><p>{copy.tip}</p></div></section>}
  {page==="journey"&&updatedAt&&<small className="last-updated">עודכן לאחרונה: {updatedAt.toLocaleTimeString("he-IL",{hour:"2-digit",minute:"2-digit"})}</small>}
  <nav className="child-bottom-nav" aria-label="ניווט בעולם האוצר"><button type="button" className={page==="journey"?"active":""} aria-current={page==="journey"?"page":undefined} onClick={()=>setPage("journey")}>🗺️<span>המסע</span></button><button type="button" className={page==="games"?"active":""} aria-current={page==="games"?"page":undefined} onClick={()=>setPage("games")}>🎮<span>משחקים</span></button><button type="button" className={page==="purses"?"active":""} aria-current={page==="purses"?"page":undefined} onClick={()=>setPage("purses")}>💰<span>קופות</span></button><button type="button" className={page==="tasks"?"active":""} aria-current={page==="tasks"?"page":undefined} onClick={()=>setPage("tasks")}>🎯<span>משימות</span></button><button type="button" className={page==="achievements"?"active":""} aria-current={page==="achievements"?"page":undefined} onClick={()=>setPage("achievements")}>🏆<span>הישגים</span></button></nav>
 </div>;
}
function SharedChildPage({token}:{token:string}){
 const [child,setChild]=useState<SharedChild|null>(null),[error,setError]=useState(""),[loading,setLoading]=useState(true),[updatedAt,setUpdatedAt]=useState(new Date());
 const refresh=useCallback(async()=>{try{const result=await api<{child:SharedChild}>("/public/child/"+token);setChild(result.child);localStorage.setItem("mypocket-child-pwa-path",window.location.pathname);setError("");setUpdatedAt(new Date());}catch{setError("הקישור אינו תקף או שבוטל. בקשו מההורה קישור חדש.");setChild(null);}finally{setLoading(false);}},[token]);
 useEffect(()=>{void refresh();const timer=window.setInterval(()=>void refresh(),30000);return()=>window.clearInterval(timer);},[refresh]);
 if(loading)return <main className="shell auth-shell"><section className="auth-card"><div className="loading-brand"><img src="/pwa-icon.svg?v=4" alt="קופת האוצר" /><h1>פותחים את הקופה...</h1></div></section></main>;
 if(error||!child)return <main className="shell auth-shell"><section className="auth-card"><div className="auth-mascot">🔒</div><h1>אי אפשר לפתוח את הקופה</h1><p>{error}</p></section></main>;
 return <main className="shell child-shell"><header className="child-topbar"><div className="brand"><img className="brand-logo" src="/pwa-icon.svg?v=4" alt="קופת האוצר" /><div><b>קופת האוצר</b><small>העולם האישי שלך</small></div></div></header><ChildAdventure child={child} tasks={child.tasks} savingsGoal={child.savingsGoal} onRefresh={()=>void refresh()} updatedAt={updatedAt}/><footer>💚 קופת האוצר · חוסכים, לומדים, מגשימים</footer></main>;
}
